React TerminalRust Handler <pre><code>import { useEffect, useRef } from 'react';
import { useWebSocket } from '../hooks/useWebSocket';

export function Terminal() {
  const containerRef = useRef&lt;HTMLDivElement&gt;(null);
  const { send, messages } = useWebSocket('/ws/terminal');

  return (
    &lt;div ref={containerRef} className="terminal-viewport"&gt;
      {messages.map((msg, i) =&gt; (
        &lt;pre key={i}&gt;{msg.data}&lt;/pre&gt;
      ))}
      &lt;input
        onKeyDown={(e) =&gt; {
          if (e.key === 'Enter') send(e.currentTarget.value);
        }}
        placeholder="Type a command..."
      /&gt;
    &lt;/div&gt;
  );
}
</code></pre> <pre><code>use axum::extract::ws::{Message, WebSocket};
use tokio::process::Command;

pub async fn handle_command(
    socket: &amp;mut WebSocket,
    cmd: &amp;str,
) -&gt; anyhow::Result&lt;()&gt; {
    let output = Command::new("sh")
        .arg("-c")
        .arg(cmd)
        .output()
        .await?;

    let text = String::from_utf8_lossy(&amp;output.stdout);
    socket.send(Message::Text(text.into())).await?;
    Ok(())
}
</code></pre>
